# 创建 Frank 用户，并设置密码，该用户可在任意主机连接该 MySQL 服务
CREATE USER 'Frank'@'%' IDENTIFIED WITH MySQL_native_password BY '********';

#为 'Frank'@'%' 用户分配主从复制权限
GRANT REPLICATION SLAVE ON *.* TO 'Frank'@'%';

